parameters.jsCode:
// Combine original audit with AI response
const auditData = $('Parse & Validate Audit JSON').first().json;
const aiRaw = $input.first()?.json || {};

let aiReport = {
  summary: "Automated rule-based verification completed.",
  overall_assessment: `Security score: ${auditData.score}/100 (${auditData.risk_level}).`,
  findings: []
};

try {
  const contentStr = aiRaw.choices?.[0]?.message?.content || "";
  if (contentStr) {
    const cleaned = contentStr.replace(/```json\n?|```/g, '').trim();
    aiReport = JSON.parse(cleaned);
  }
} catch (e) {
  aiReport.summary = "AI report processed with rule fallback.";
}

return [{
  json: {
    ...auditData,
    ai_report: aiReport
  }
}];

